// src/components/Hero.jsx
import React from 'react';
import { motion } from 'framer-motion';

export default function Hero() {
  return (
    <section
      id="hero"
      className="flex flex-col-reverse md:flex-row items-center gap-8 max-w-3xl mx-auto text-center md:text-left"
    >
      {/* Text block */}
      <div>
        <motion.h1
          className="text-4xl font-bold"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          Srivikaat Ravi — Aspiring Electrical &amp; Computer Engineer
        </motion.h1>
        <motion.p
          className="mt-4 text-lg text-gray-600"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3 }}
        >
          “3 years of experience in leading and founding STEM initiatives.
          Successfully organized team management for FRC Team 4450.
          Founded FIRST STEP ORG, reaching 60+ students in two years.”
        </motion.p>
        <div className="mt-6 flex justify-center md:justify-start gap-4">
          <a
            href="/resume.pdf"
            download
            className="px-4 py-2 border rounded-lg hover:bg-gray-100"
          >
            Download Résumé
          </a>
          <a
            href="https://www.linkedin.com/in/srivikaatr"
            target="_blank"
            rel="noreferrer"
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            View LinkedIn
          </a>
        </div>
      </div>

      {/* Profile image */}
      <motion.img
        src="/profile.jpg"
        alt="Srivikaat Ravi"
        className="w-32 h-32 md:w-48 md:h-48 rounded-full object-cover shadow-lg"
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ delay: 0.2 }}
      />
    </section>
  );
}
